// 1. Obfuscator-LLVM family — open-source LLVM-pass obfuscators leave their project names in .comment / crash handlers / logs
let llvm_fam = [
  ["obfuscator-llvm", "Obfuscator-LLVM", "HIGH", "Original Obfuscator-LLVM project reference — control-flow flattening, bogus control flow, instruction substitution"],
  ["ollvm", "OLLVM Marker", "HIGH", "OLLVM reference — control-flow flattening / bogus control flow obfuscation"],
  ["hikari", "Hikari Obfuscator", "HIGH", "Hikari — LLVM obfuscation fork with anti-hook and function-wrapper passes"],
  ["goron", "Goron Obfuscator", "HIGH", "Goron — LLVM obfuscator with indirect branching and function splitting"],
  ["armariris", "Armariris Obfuscator", "HIGH", "Armariris — LLVM obfuscation fork (Control Flow + String encryption)"],
  ["yanso", "YANSOllvm Obfuscator", "MEDIUM", "YANSOllvm — yet another LLVM obfuscation suite"],
  ["movfuscator", "Movfuscator", "MEDIUM", "Movfuscator reference — compiles code to mov-only instructions (extreme case)"],
  ["tigress", "Tigress Obfuscator", "MEDIUM", "Tigress — C source-level diversifying obfuscator (virtualization, flattening)"],
  ["llvm-obfuscator", "LLVM Obfuscator Tag", "HIGH", "Generic LLVM-obfuscator build tag"]
];
for sig in llvm_fam {
  let hits = find_strings(sig[0]);
  for h in hits {
    report(sig[1], h.address, sig[2], h.value + " (" + sig[3] + ")");
  }
  let syms = find_symbols(sig[0]);
  for s in syms {
    report(sig[1] + " symbol", s.address, sig[2], s.name + " (" + sig[3] + ")");
  }
}

// 2. String-encryption frameworks — their runtime markers leak into the binary
let strf = [
  ["stringfog", "StringFog Framework", "HIGH", "StringFog — byte-level string encryption at build time"],
  ["dexguard", "DexGuard", "HIGH", "DexGuard — commercial obfuscator (string encryption, flow obfuscation)"],
  ["allatori", "Allatori", "HIGH", "Allatori — commercial Java obfuscator with string encryption"],
  ["zelix", "Zelix KlassMaster", "HIGH", "Zelix KlassMaster — commercial obfuscator (method-name mangling, string encryption)"],
  ["proguard", "ProGuard Artifact", "MEDIUM", "ProGuard reference — renamed/mapped symbols (mapping.txt consumers)"],
  ["mapping.txt", "ProGuard/R8 Mapping", "MEDIUM", "Deobfuscation mapping file reference — obfuscated build artifact"]
];
for sig in strf {
  let hits = find_strings(sig[0]);
  for h in hits {
    report(sig[1], h.address, sig[2], h.value + " (" + sig[3] + ")");
  }
}

// 3. Obfuscated symbol naming conventions — deliberate rename passes leave tell-tale prefixes
let namings = [
  ["obf_", "obf_ Symbol Prefix", "MEDIUM", "Symbols deliberately prefixed obf_ — custom rename pass"],
  ["_obfuscated", "_obfuscated Symbol Suffix", "MEDIUM", "Symbols suffixed _obfuscated — rename pass artifact"],
  ["virtual_func_", "VM-dispatch Symbol Prefix", "MEDIUM", "virtual_func_ naming — bytecode-VM or dispatcher-generated code"],
  ["native_method_", "Generated-method Symbol Prefix", "MEDIUM", "native_method_ naming — machine-generated stubs (obfuscator or packer runtime)"]
];
for sig in namings {
  let syms = find_symbols(sig[0]);
  for s in syms {
    report(sig[1], s.address, sig[2], s.name + " (" + sig[3] + ")");
  }
}
